SELECT room_id, room_code, host_id, room_title, created_at, deleted_at
FROM room
WHERE room_id = #{roomId}

SELECT room_id, room_code, host_id, room_title, created_at, deleted_at
FROM room
WHERE room_code = #{roomCode}

SELECT COUNT(*)
FROM room_participant
WHERE room_id = #{roomId}
  AND user_id = #{userId}

SELECT COUNT(*)
FROM room_participant
WHERE room_id = #{roomId}
  AND user_id IN
  #{id}
